class Solution { int f(int[]p,int x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}public List<Integer> minimumSpanningTreeEdges(int n,int[][]e){Integer[]idx=new Integer[e.length];for(int i=0;i<e.length;i++)idx[i]=i;Arrays.sort(idx,(i,j)->{int c=Integer.compare(e[i][2],e[j][2]);return c!=0?c:Integer.compare(i,j);});int[]p=new int[n];for(int i=0;i<n;i++)p[i]=i;List<Integer>out=new ArrayList<>();for(int i:idx){int a=f(p,e[i][0]),b=f(p,e[i][1]);if(a!=b){p[a]=b;out.add(i);}}if(out.size()!=n-1)return new ArrayList<>();Collections.sort(out);return out;} }
